static void flow_offload_decap_tunnel ( const struct flow_offload * flow , enum flow_offload_tuple_dir dir , struct nf_flow_rule * flow_rule ) { const struct flow_offload_tuple * other_tuple ; struct flow_action_entry * entry ; struct dst_entry * dst ; other_tuple = & flow -> tuplehash [ ! dir ] . tuple ; dst = other_tuple -> dst_cache ; if ( dst && dst -> lwtstate ) { struct ip_tunnel_info * tun_info ; tun_info = lwt_tun_info ( dst -> lwtstate ) ; if ( tun_info && ( tun_info -> mode & IP_TUNNEL_INFO_TX ) ) { entry = flow_action_entry_next ( flow_rule ) ; entry -> id = FLOW_ACTION_TUNNEL_DECAP ; } } } 